set -u
WP=$((7804 + 20000)); LP=$((7804 + 20001)); export WERKBANK_PORT=$WP
L="${TEMP:-/tmp}/punkte-g5-$WP"; mkdir -p "$L"; W="node scripts/werkbank.cjs"; FRISCH=1
boot() { if [ -z "$FRISCH" ]; then node "$PUNKTE_MASCHINE" grundstellung > "$L/grund.txt" 2>&1 || { echo "@@PUNKTE@@ START ROT"; cat "$L/grund.txt"; exit 3; }; fi; FRISCH=; if [ $# -gt 0 ]; then timeout 300 $W umstellen "$@" > "$L/boot.txt" 2>&1 || { echo "@@PUNKTE@@ START ROT"; tail -5 "$L/boot.txt"; exit 3; }; fi; }
teil() { echo "@@PUNKTE@@ $1"; shift; timeout 900 "$@"; echo "@@PUNKTE@@ EXIT $?"; }
A=$(cygpath -m 'C:\Users\micha\Desktop\AnazhRealm-OMEN\n0611-pm\meisterkarte-quelle\punkte\messung\roh\1feab29c-gtx\karte2.mensch.stadt.siedlungsnetz_1.json')
( node scripts/diag-settlement.cjs --nur-z --zipf; echo "@@PUNKTE@@ EXIT $?" ) > "$L/zipf.out" 2>&1 &
boot
timeout 60 $W fenster 1600 900 > /dev/null 2>&1
timeout 120 $W eval 'const g = r._genesisMitte(); const out = []; for (let cx = -10; cx <= 10; cx++) for (let cz = -10; cz <= 10; cz++) { const i = r._autoSettlementCellInfo(cx, cz); if (!i || !(i.stufe > 0)) continue; const d = Math.hypot(i.x - g.x, i.z - g.z); if (d > 2000) continue; out.push({ cx, cz, nH: i.nH, stufe: i.stufe, d: Math.round(d), site: r._autoSettlementFindSite(i) }); } out.sort((a, b) => a.d - b.d); const c = out.find((o) => o.site); let hill = null; if (c) for (const R of [180, 220, 260]) for (let k = 0; k < 32; k++) { const a = (k / 32) * 2 * Math.PI, x = c.site.x + Math.cos(a) * R, z = c.site.z + Math.sin(a) * R, y = r.getTerrainHeightAt(x, z); if (Number.isFinite(y) && r._landAt(x, z, 0.2) && (!hill || y > hill.y)) hill = { x, y, z, R }; } window.__stadtWahl = { c, hill }; return { seed: r.state.worldMeta && r.state.worldMeta.seed, staedte: out.length, wahl: c ? { cx: c.cx, cz: c.cz, nH: c.nH, stufe: c.stufe, d: c.d } : null, hill };' > "$L/wahl.json" 2>&1; echo '@@PUNKTE@@ WAHL'; cat "$L/wahl.json"; echo
HILL=$(node -e 'const t = require("fs").readFileSync(process.argv[1], "utf8"); const e = JSON.parse(t.slice(t.indexOf("{"))).ergebnis; console.log(e.hill ? e.hill.x.toFixed(1) + " " + e.hill.z.toFixed(1) : "")' "$L/wahl.json" 2> /dev/null)
[ -n "$HILL" ] || { echo '@@PUNKTE@@ KEINE STADT MIT ORT BINNEN 2 KM'; exit 4; }
timeout 300 $W eval 'const c = window.__stadtWahl.c.site, h = window.__stadtWahl.hill, M = () => r.state.stlMauer; const steht = () => (M() ? M().top : 0) > 0 && !(r._autoSettlementQueue && r._autoSettlementQueue.plan) && !r._autoSettlementPendingKey; r.state.playerMesh.position.set(h.x, r._voxelSurfaceY(h.x, h.z) + 1.8, h.z); const zurueck = leihe(window, { __anazhAutoSettlement: true }), decke = leihe(r.state, { perfTargetMs: 1000 }); let takte = null; try { takte = await __gebautNach("die Stadt vom Hügel", { fertig: steht, bau: () => {}, takt: async () => { __werkTakt(); await new Promise((ok) => requestAnimationFrame(ok)); }, max: 1800 }); } catch (e) { takte = String((e && e.message) || e).slice(0, 300); } finally { zurueck(); decke(); } const P = M(), q = r._autoSettlementQueue; let haeuser = 0; for (const e of r.state.architectures) if (e && /^haus_/.test(e.type) && Math.hypot(e.position.x - c.x, e.position.z - c.z) < 400) haeuser++; return { mauer: P ? P.top : 0, zug: !!(q && q.plan), pending: r._autoSettlementPendingKey || null, haeuser, takte, zugHaken: window.__anazhAutoSettlement };' > "$L/stand.json" 2>&1
echo '@@PUNKTE@@ STAND'; cat "$L/stand.json"; echo
timeout 60 $W eval 'const c = window.__stadtWahl.c.site; let v2 = null; for (const p of r._ortPlaene.values()) if (p && p.ort && p.mauer && (!v2 || Math.hypot(p.ort.x - c.x, p.ort.z - c.z) < Math.hypot(v2.ort.x - c.x, v2.ort.z - c.z))) v2 = p; if (!v2) return { fehler: "kein Ortsplan mit Mauer" }; const o = v2.ort, cand = []; for (const f of v2.felder || []) cand.push({ x: o.x + f.cx, z: o.z + f.cz, art: "acker" }); for (const fw of v2.feldwege || []) for (const q of fw.pts) cand.push({ x: o.x + q.x, z: o.z + q.z, art: "feldweg" }); let best = null; for (const q of cand) { const d = Math.hypot(q.x - o.x, q.z - o.z); if (d < 70 || d > 260) continue; const y = r.getTerrainHeightAt(q.x, q.z); if (!Number.isFinite(y)) continue; if (!best || y > best.y) best = Object.assign({ y, d: Math.round(d) }, q); } if (!best) return { fehler: "kein Acker oder Feldweg 70–260 m vor der Stadt" }; const cy = r.getTerrainHeightAt(o.x, o.z); const pose = [best.x, best.y + 1.7, best.z, o.x, cy + 5, o.z].map((v) => +v.toFixed(2)); window.__stadtKamera = { v2, pose }; return { pose, art: best.art, d: best.d, hoeher: Math.round((best.y - cy) * 10) / 10, segs: v2.mauer.segs.length, tuerme: v2.mauer.towers.length };' > "$L/kamera.json" 2>&1; echo '@@PUNKTE@@ KAMERA'; cat "$L/kamera.json"; echo
K=$(node -e 'const t = require("fs").readFileSync(process.argv[1], "utf8"); const e = JSON.parse(t.slice(t.indexOf("{"))).ergebnis; console.log(e.pose ? e.pose.join(" ") : "")' "$L/kamera.json" 2> /dev/null)
[ -n "$K" ] || { echo '@@PUNKTE@@ KEINE KAMERA'; exit 5; }
timeout 60 $W eval 'const SK = window.__stadtKamera; if (!SK) return { fehler: "keine Kamera der Stadt (STADT_KAMERA lief nicht)" }; const v2 = SK.v2, K = SK.pose, o = v2.ort; const P = r.state.stlMauer, wk = r._wegeKarteEnsure(); const box = (wk.siedlungen || []).filter((b) => b && b.mauerVon && (b.mauerVon === v2 || (b.mauerVon.ort && Math.hypot(b.mauerVon.ort.x - o.x, b.mauerVon.ort.z - o.z) < 1))).pop(); if (!P || !box) return { fehler: "die Mauer der Stadt steht nicht im Pool" }; const SM = globalThis.__fachwerkCore.STADTMAUER, cam = r.state.camera.clone(), M4 = cam.matrixWorld.clone(), pos = cam.position.clone(), q = cam.quaternion.clone(), sk = cam.position.clone(), V = cam.position.clone(); const boden = (x, z) => { const y = r._voxelSurfaceY(x, z); return Number.isFinite(y) ? y : r.getTerrainHeightAt(x, z); }; cam.aspect = 1600 / 900; cam.position.set(K[0], K[1], K[2]); cam.lookAt(K[3], K[4], K[5]); cam.updateProjectionMatrix(); cam.updateMatrixWorld(true); const waende = [], tuerme = []; let spalt = -Infinity, bei = null; for (let i = box.streifen[0]; i < box.streifen[1]; i++) { M4.fromArray(P.mesh.instanceMatrix.array, i * 16); M4.decompose(pos, q, sk); if (Math.abs(sk.x - SM.wand.dick) < 0.01 && sk.y > SM.wand.hoch) { const w = { x: pos.x, z: pos.z, sp: -Infinity }; for (const t of [-0.5, -0.25, 0, 0.25, 0.5]) { V.set(0, -0.5, t).applyMatrix4(M4); const g = V.y - boden(V.x, V.z); if (g > w.sp) w.sp = g; if (g > spalt) { spalt = g; bei = [+V.x.toFixed(1), +V.z.toFixed(1)]; } } w.top = V.set(0, 0.5, 0).applyMatrix4(M4).clone(); waende.push(w); } else if (Math.abs(sk.x - SM.turm.breit) < 0.01 && sk.y > SM.turm.hoch) tuerme.push([pos.x, pos.z]); } const plan = v2.mauer.segs.map((s) => { const mx = o.x + (s.x0 + s.x1) / 2, mz = o.z + (s.z0 + s.z1) / 2; return { land: r._landAt(mx, mz, 0.2), steht: waende.some((w) => Math.hypot(w.x - mx, w.z - mz) < 1.5) }; }); let imRahmen = 0, frei = 0; const E = cam.position; for (const w of waende) { const v = w.top.clone().project(cam); if (!(Math.abs(v.x) <= 1 && Math.abs(v.y) <= 1 && v.z > -1 && v.z < 1)) continue; imRahmen++; const L = E.distanceTo(w.top); let vor = false; for (let s = 1; s < L - 1 && !vor; s += 1) { const t = s / L; if (E.y + (w.top.y - E.y) * t < r.getTerrainHeightAt(E.x + (w.top.x - E.x) * t, E.z + (w.top.z - E.z) * t) - 0.2) vor = true; } if (!vor) frei++; } return { geplant: plan.length, gebaut: plan.filter((p) => p.steht).length, wasser: plan.filter((p) => !p.land).length, offen: plan.filter((p) => !p.steht).length, tore: (v2.mauer.gates || []).length, tuerme: [v2.mauer.towers.length, tuerme.length], waende: waende.length, spaltM: Number.isFinite(spalt) ? +spalt.toFixed(3) : null, bei, imRahmen, frei };' > "$L/mauer.json" 2>&1; echo '@@PUNKTE@@ MAUER'; cat "$L/mauer.json"; echo
rm -f "$L/stadt-mittag.abnahme.json" "$L/stadt-daemmerung.abnahme.json"
teil MITTAG $W bild $K --uhr 0.5 --datei "$L/stadt-mittag.png" --w 1600 --h 900
teil DAEMMERUNG $W bild $K --uhr 0.25 --datei "$L/stadt-daemmerung.png" --w 1600 --h 900
node -e 'const f = require("fs"), l = (n) => { try { return JSON.parse(f.readFileSync(process.argv[2] + "/stadt-" + n + ".abnahme.json", "utf8")); } catch (e) { return null; } }; f.writeFileSync(process.argv[1], JSON.stringify({ mittag: l("mittag"), daemmerung: l("daemmerung") }))' "$A" "$L"
wait
echo "@@PUNKTE@@ Z"; cat "$L/zipf.out"